<?php
declare(strict_types=1);
require dirname(__DIR__).'/auth_store.php';
header('Content-Type: application/json; charset=UTF-8');
header('Cache-Control: no-store, no-cache, must-revalidate');

const BT_FILE=TT_DATA_DIR.'/accounts.json';
const BT_MASTER=__DIR__.'/../accounts/accounting_master_v1.json';

function bt_out(array $x,int $s=200):never{http_response_code($s);echo json_encode($x,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);exit;}
function bt_default():array{return ['revision'=>0,'journals'=>[],'commodityBills'=>[],'brokerageBills'=>[],'brokeragePayments'=>[],'brokerageWhtDeposits'=>[],'bankAccountSettings'=>[]];}
function bt_read():array{tt_ensure_data_dir();if(!is_file(BT_FILE))return bt_default();$h=fopen(BT_FILE,'r');if($h===false||!flock($h,LOCK_SH))throw new RuntimeException('store');try{$raw=stream_get_contents($h);}finally{flock($h,LOCK_UN);fclose($h);} $s=$raw?json_decode($raw,true):null;return is_array($s)?array_replace_recursive(bt_default(),$s):bt_default();}
function bt_can_write(array $u):bool{if(($u['role']??'')==='Super Admin')return true;$p=$u['permissions']['Accounts']??null;if($p==='all')return true;if(!is_array($p))return false;if(in_array('Create',$p,true)||in_array('Edit',$p,true)||in_array('Approve',$p,true))return true;foreach($p as $a)if(is_array($a)&&(in_array('Create',$a,true)||in_array('Edit',$a,true)||in_array('Approve',$a,true)))return true;return false;}
function bt_date(string $v):string{if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$v))bt_out(['ok'=>false,'error'=>'Valid payment date required.'],422);return $v;}
function bt_money(mixed $v):float{$n=round((float)$v,2);if($n<=0)bt_out(['ok'=>false,'error'=>'Amount must be greater than zero.'],422);return $n;}
function bt_master():array{$raw=is_file(BT_MASTER)?file_get_contents(BT_MASTER):false;$m=$raw?json_decode($raw,true):null;if(!is_array($m))throw new RuntimeException('master');return $m;}
function bt_names():array{$o=[];foreach((array)(bt_master()['chart']??[]) as $a)if(is_array($a)&&isset($a['code']))$o[(string)$a['code']]=(string)($a['name']??$a['code']);foreach((array)(bt_master()['peopleSubledgers']??[]) as $a)if(is_array($a)&&isset($a['code']))$o[(string)$a['code']]=(string)($a['name']??$a['code']);return $o;}
function bt_line(string $a,float $d,float $c,array $n,array $extra=[]):array{if(!isset($n[$a]))bt_out(['ok'=>false,'error'=>'Account '.$a.' is not configured.'],422);return array_merge(['account'=>$a,'accountName'=>$n[$a],'debit'=>round($d,2),'credit'=>round($c,2)],$extra);}
function bt_next(array $items,string $p):string{$n=count($items)+1;do{$id=$p.'-'.gmdate('Y').'-'.str_pad((string)$n,6,'0',STR_PAD_LEFT);$n++;}while(isset($items[$id]));return $id;}
function bt_entity(string $v):string{$v=strtoupper(trim($v));if(!in_array($v,['TTI','BRM'],true))bt_out(['ok'=>false,'error'=>'Brokerage WHT is available for TTI or BRM.'],422);return $v;}
function bt_linked_entity(string $v):string{$u=strtoupper($v);if(str_contains($u,'BRM')||str_contains($u,'BUKSH RICE'))return 'BRM';if(str_contains($u,'TTI')||str_contains($u,'TRANSTRADE INTERNATIONAL'))return 'TTI';if(str_contains($u,'TG')||str_contains($u,'TRANS GRAINS'))return 'TG';return '';}
function bt_bank(string $id,string $entity,array $store):array{foreach((array)(tt_list_masters()['banks']??[]) as $r){if(!is_array($r)||(string)($r['id']??'')!==$id)continue;$v=array_values((array)($r['values']??[]));while(count($v)<14)$v[]='';if(bt_linked_entity((string)$v[1])!==$entity)bt_out(['ok'=>false,'error'=>'Selected bank does not belong to these company books.'],422);$s=is_array($store['bankAccountSettings'][$id]??null)?$store['bankAccountSettings'][$id]:[];if(empty($s['active'])||empty($s['allowPayments']))bt_out(['ok'=>false,'error'=>'Selected bank is not enabled for payments in Accounts.'],422);if(strtoupper(trim((string)$v[7]))!=='PKR')bt_out(['ok'=>false,'error'=>'Brokerage WHT payment requires a PKR company bank.'],422);return ['id'=>$id,'bankName'=>(string)$v[4],'accountTitle'=>(string)$v[3]];}bt_out(['ok'=>false,'error'=>'Selected bank was not found.'],404);}
function bt_person_account(string $p):string{$m=['SALMAN'=>'REIMB-SALMAN','TALHA'=>'REIMB-TALHA','ABU'=>'REIMB-ABU','TAYYAB'=>'REIMB-TAYYAB'];$k=strtoupper(trim($p));if(!isset($m[$k]))bt_out(['ok'=>false,'error'=>'Selected family/staff payer is not configured.'],422);return $m[$k];}
function bt_wht_rows(array $s,string $entity,string $broker):array{$rows=[];foreach((array)($s['commodityBills']??[]) as $id=>$b){if(!is_array($b)||($b['entity']??'')!==$entity||strcasecmp((string)($b['broker']??''),$broker)!==0)continue;$w=round((float)($b['brokerageWithholding']??0),2);if($w<=0)continue;$rows[]=['key'=>'AUTO|'.$id,'date'=>(string)($b['billDate']??''),'wht'=>$w,'source'=>'Purchase Bill'];}foreach((array)($s['brokerageBills']??[]) as $id=>$b){if(!is_array($b)||($b['entity']??'')!==$entity||strcasecmp((string)($b['broker']??''),$broker)!==0||($b['status']??'Posted')==='Cancelled')continue;$w=round((float)($b['whtAmount']??0),2);if($w<=0)continue;$rows[]=['key'=>'SEPARATE|'.$id,'date'=>(string)($b['billDate']??''),'wht'=>$w,'source'=>'Separate Brokerage Bill'];}$paid=[];foreach((array)($s['brokerageWhtDeposits']??[]) as $d){if(!is_array($d)||($d['entity']??'')!==$entity||strcasecmp((string)($d['broker']??''),$broker)!==0||!in_array((string)($d['status']??'Posted'),['Posted','Approved / Posted','Approved'],true))continue;foreach((array)($d['allocations']??[]) as $a){if(!is_array($a))continue;$k=(string)($a['sourceKey']??'');$paid[$k]=round(($paid[$k]??0)+(float)($a['amount']??0),2);}}foreach($rows as &$r){$r['deposited']=round((float)($paid[$r['key']]??0),2);$r['outstanding']=max(0,round($r['wht']-$r['deposited'],2));}unset($r);$rows=array_values(array_filter($rows,fn($r)=>$r['outstanding']>.005));usort($rows,static fn($a,$b)=>strcmp((string)$a['date'],(string)$b['date'])?:strcmp((string)$a['key'],(string)$b['key']));return $rows;}

try{$u=tt_require_login();if(!tt_user_can_open_module($u,'Accounts'))bt_out(['ok'=>false,'error'=>'Accounts permission required.'],403);if($_SERVER['REQUEST_METHOD']==='GET'){$entity=bt_entity((string)($_GET['entity']??'TTI'));$s=bt_read();$brokers=[];foreach((array)($s['commodityBills']??[]) as $b)if(is_array($b)&&($b['entity']??'')===$entity&&(float)($b['brokerageWithholding']??0)>0)$brokers[]=(string)($b['broker']??'');foreach((array)($s['brokerageBills']??[]) as $b)if(is_array($b)&&($b['entity']??'')===$entity&&(float)($b['whtAmount']??0)>0)$brokers[]=(string)($b['broker']??'');$brokers=array_values(array_unique(array_filter(array_map('trim',$brokers))));sort($brokers);$summary=[];foreach($brokers as $b){$rows=bt_wht_rows($s,$entity,$b);$out=round(array_sum(array_column($rows,'outstanding')),2);if($out>0)$summary[]=['broker'=>$b,'outstanding'=>$out,'rows'=>$rows];}bt_out(['ok'=>true,'brokers'=>$summary]);}
if($_SERVER['REQUEST_METHOD']!=='POST')bt_out(['ok'=>false,'error'=>'Method not allowed.'],405);if(!bt_can_write($u))bt_out(['ok'=>false,'error'=>'Accounts approval / edit permission required.'],403);$b=json_decode(file_get_contents('php://input')?:'',true);if(!is_array($b)||!tt_verify_csrf((string)($b['csrf']??'')))bt_out(['ok'=>false,'error'=>'Session expired. Refresh and try again.'],419);if(($b['action']??'')!=='deposit_wht')bt_out(['ok'=>false,'error'=>'Unknown Brokerage action.'],422);$entity=bt_entity((string)($b['entity']??''));$date=bt_date((string)($b['date']??''));$broker=trim((string)($b['broker']??''));if($broker==='')bt_out(['ok'=>false,'error'=>'Broker is required.'],422);$amount=bt_money($b['amount']??0);$source=strtoupper(trim((string)($b['sourceType']??'')));$sourceName=trim((string)($b['sourceName']??''));$reference=trim((string)($b['reference']??''));$bankId=trim((string)($b['bankAccountId']??''));tt_ensure_data_dir();$h=fopen(BT_FILE,'c+');if($h===false||!flock($h,LOCK_EX))throw new RuntimeException('store');try{rewind($h);$raw=stream_get_contents($h);$s=$raw?json_decode($raw,true):null;if(!is_array($s))$s=bt_default();$s=array_replace_recursive(bt_default(),$s);$rows=bt_wht_rows($s,$entity,$broker);$total=round(array_sum(array_column($rows,'outstanding')),2);if($amount>$total+.005)bt_out(['ok'=>false,'error'=>'Deposit exceeds this broker\'s outstanding brokerage WHT.'],422);$alloc=[];$left=$amount;foreach($rows as $r){if($left<=.005)break;$a=min($left,(float)$r['outstanding']);$alloc[]=['sourceKey'=>$r['key'],'source'=>$r['source'],'sourceDate'=>$r['date'],'amount'=>round($a,2)];$left=round($left-$a,2);}if($left>.005)throw new RuntimeException('allocation');$names=bt_names();$credit='';$extra=[];$meta=['broker'=>$broker,'paymentSource'=>$source,'sourceName'=>$sourceName];if($source==='BANK'){$bank=bt_bank($bankId,$entity,$s);$credit='1110';$extra=['bankAccountId'=>$bankId,'bankName'=>$bank['bankName'],'bankAccountTitle'=>$bank['accountTitle']];$meta=array_merge($meta,$extra);}elseif($source==='CASH'){$credit='1120';}elseif($source==='THIRD_PARTY'){if($sourceName==='')bt_out(['ok'=>false,'error'=>'Third-party payer name is required.'],422);$credit='2520';}elseif($source==='DIRECTOR_FAMILY'){if($sourceName==='')bt_out(['ok'=>false,'error'=>'Family / staff payer is required.'],422);$credit=bt_person_account($sourceName);}elseif($source==='GROUP_ENTITY'){if($sourceName==='')bt_out(['ok'=>false,'error'=>'Group entity is required.'],422);$credit='2500';}elseif($source==='OTHER_ADJUSTMENT'){if($sourceName==='')bt_out(['ok'=>false,'error'=>'Other source description is required.'],422);$credit='2520';}else bt_out(['ok'=>false,'error'=>'Select Bank, Cash, or an approved Other Source.'],422);$jid=bt_next((array)$s['journals'],'AUTO');$lines=[bt_line('2300',$amount,0,$names,['broker'=>$broker]),bt_line($credit,0,$amount,$names,$extra)];$s['journals'][$jid]=['id'=>$jid,'entity'=>$entity,'date'=>$date,'sourceType'=>'BROKERAGE_WHT_DEPOSIT','reference'=>$reference?:$jid,'narration'=>'Brokerage WHT deposit — '.$broker,'lines'=>$lines,'totalDebit'=>$amount,'totalCredit'=>$amount,'status'=>'Posted','meta'=>array_merge($meta,['allocations'=>$alloc]),'createdAt'=>gmdate('c'),'createdBy'=>(string)($u['full_name']??$u['username']??'Accounts'),'userId'=>(int)($u['id']??0)];$id=bt_next((array)$s['brokerageWhtDeposits'],'BWHT');$s['brokerageWhtDeposits'][$id]=array_merge(['id'=>$id,'entity'=>$entity,'broker'=>$broker,'date'=>$date,'amount'=>$amount,'sourceType'=>$source,'sourceName'=>$sourceName,'reference'=>$reference,'journalId'=>$jid,'allocations'=>$alloc,'status'=>'Posted','createdAt'=>gmdate('c'),'createdBy'=>(string)($u['full_name']??$u['username']??'Accounts')],$extra);$s['revision']=(int)($s['revision']??0)+1;rewind($h);ftruncate($h,0);fwrite($h,json_encode($s,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR));fflush($h);}finally{flock($h,LOCK_UN);fclose($h);}bt_out(['ok'=>true,'deposit'=>$s['brokerageWhtD